func sumTo(n int) (total, count int) {
    for i := 1; i <= n; i++ {
        total += i
        count++
    }
    return
}

func main() {
    t, c := sumTo(4)
    fmt.Println(t, c)
    t, c = sumTo(0)
    fmt.Println(t, c)
}

func find(k, lo, hi int) (n int, ok bool) {
    for i := lo; i <= hi; i++ {
        if i%k == 0 {
            n = i
            ok = true
            return
        }
    }
    return
}

func main() {
    n, ok := find(7, 10, 20)
    fmt.Println(n, ok)
    n, ok = find(7, 15, 20)
    fmt.Println(n, ok)
}

